			}
		}

		private static float RotationTowardsEdge(int x, int y, int middle)
		{
			if (y > middle)
			{
				return 270f;
			}
			if (x > middle)
			{
				return 0f;
			}
			if (y < middle)
			{
				return 90f;
			}
			return 180f;
		}

		private static float RotationForQuadrant(int x, int y, int middle)
		{
			if (x > middle)
			{
