			{
				sim.farm.grid.SetGround(base.pos, "rice_terrace");
			}
		}

		protected override void OnFullyGrown()
		{
			base.OnFullyGrown();
			sim.farm.grid.SetGround(base.pos, "dry_rice_terrace");
		}
	}
}